+    let PdfObject::Array(elements) = Parser::new(source.as_bytes())
+        .parse_object()
+        .expect("ファイルID配列をパースできる")
+    else {
+        panic!("ファイルIDは配列");
+    };
+    FileId::from_array(elements.into_vec()).expect("ファイルIDを構築できる")
